// The pictures in the README, drawn from the app itself.
//
// Every screen here is fed made-up data through the same stand-in for the PC
// that the tests use, so no real project, session or conversation can ever end
// up in a picture. Run it from the repo root with:
//
//   npm run screenshots
//
// It writes PNGs to docs/screenshots/. Its name has no _test on purpose: the
// pictures are regenerated by hand, not compared on every test run, because
// text renders slightly differently from one machine to the next.
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:loop_app/chat.dart';
import 'package:loop_app/main.dart';
import 'package:loop_app/pane.dart';
import 'package:loop_app/shell.dart';
import 'package:loop_app/talk.dart';
import 'package:loop_app/theme.dart';
import 'package:loop_app/voice.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Flutter ships Roboto and the Material icons with the SDK; tests draw text
/// as plain boxes unless they are loaded.
String _fontsDir() {
  final root = Platform.environment['FLUTTER_ROOT'];
  if (root != null && root.isNotEmpty) {
    return '$root/bin/cache/artifacts/material_fonts';
  }
  // flutter_tester sits in <root>/bin/cache/artifacts/engine/<platform>/.
  var d = File(Platform.resolvedExecutable).parent;
  for (var i = 0; i < 5; i++) {
    d = d.parent;
  }
  return '${d.path}/bin/cache/artifacts/material_fonts';
}

Future<void> _loadFonts() async {
  final dir = _fontsDir();
  Future<ByteData> font(String name) async {
    final f = File('$dir/$name');
    if (!f.existsSync()) {
      throw StateError('Font not found: ${f.path}. Is FLUTTER_ROOT set?');
    }
    return ByteData.sublistView(Uint8List.fromList(await f.readAsBytes()));
  }

  final roboto = FontLoader('Roboto');
  for (final n in const [
    'roboto-regular.ttf',
    'roboto-medium.ttf',
    'roboto-bold.ttf',
  ]) {
    roboto.addFont(font(n));
  }
  await roboto.load();
  final icons = FontLoader('MaterialIcons')
    ..addFont(font('materialicons-regular.otf'));
  await icons.load();
}

const _phone = Size(390, 844);
const _out = '../../../docs/screenshots';

void main() {
  final now = DateTime.now().millisecondsSinceEpoch;

  setUpAll(_loadFonts);

  setUp(() {
    SharedPreferences.setMockInitialValues({});
    Pane.close();
    bridge.hear({'t': 'ready', 'host': 'Workstation', 'window': true});
    bridge.hear({
      't': 'state',
      's': {
        'projects': [
          {
            'dir': 'acme-shop',
            'title': 'Acme Shop',
            'count': 4,
            'live': 1,
            'team': true,
            'server': '',
            'mtime': now,
          },
        ],
        'running': const [],
        'recent': const [],
        'roles': const [],
        'workspaces': const [],
        'tabs': const [],
        'accounts': const [],
      },
    });
  });

  tearDown(() {
    bridge.onAsk = null;
    bridge.disconnect();
    Pane.close();
  });

  Future<void> phone(WidgetTester t) async {
    t.view.devicePixelRatio = 3;
    t.view.physicalSize = _phone * 3;
    await t.binding.setSurfaceSize(_phone);
    addTearDown(() {
      t.view.reset();
      return t.binding.setSurfaceSize(null);
    });
  }

  Future<void> settle(WidgetTester t, [int times = 10]) async {
    for (var i = 0; i < times; i++) {
      await t.pump(const Duration(milliseconds: 120));
    }
  }

  // Shadows are switched off in tests; a picture should look like the app.
  Future<void> shoot(WidgetTester t, String name) async {
    debugDisableShadows = false;
    await t.pump();
    await expectLater(find.byType(MaterialApp), matchesGoldenFile('$_out/$name.png'));
    debugDisableShadows = true;
  }

  // Timers and animations end with the screen, so none is left running. A
  // question to the PC waits up to 30 seconds for an answer that never comes.
  Future<void> away(WidgetTester t) async {
    await t.pumpWidget(const SizedBox());
    await t.pump(const Duration(seconds: 31));
  }

  Map<String, dynamic> lead(String key, Map<String, dynamic> report) => {
    'key': key,
    'id': key == 'ceo'
        ? '11111111-1111-4111-8111-111111111111'
        : '22222222-2222-4222-8222-222222222222',
    'title': key.toUpperCase(),
    'lamp': 'idle',
    'status': '',
    'asking': false,
    'report': report,
  };

  testWidgets('home: what needs you, from two leads', (t) async {
    await phone(t);
    bridge.onAsk = (m) => switch (m['action']) {
      'home' => {
        'projects': [
          {
            'dir': 'acme-shop',
            'title': 'Acme Shop',
            'mtime': now,
            'leads': [
              lead('ceo', {
                'kind': 'plan',
                'at': now - 4 * 60000,
                'lead': 'pricing page',
                'bullets': [
                  'Marketing drafts the copy for three plans',
                  'The CTO builds the page and the toggle',
                  'I review it on staging before it goes live',
                ],
                'need': '',
                'goal': 'add a pricing page with a yearly toggle',
                'goalAt': now - 6 * 60000,
              }),
              lead('cto', {
                'kind': 'done',
                'at': now - 9 * 60000,
                'lead': 'checkout timeout fixed',
                'bullets': [
                  'The payment call now waits 30 seconds, not 5',
                  'One retry when the gateway answers 504',
                  'All 212 tests pass on staging',
                ],
                'need': 'ship it?',
                'goal': 'fix the checkout timeout on big carts',
                'goalAt': now - 31 * 60000,
              }),
            ],
          },
        ],
      },
      'tokens' => {
        'fresh': 41200,
        'cached': 380000,
        'calls': 58,
        'sessions': 3,
      },
      _ => null,
    };
    await t.pumpWidget(
      MaterialApp(
        debugShowCheckedModeBanner: false,
        theme: loopTheme(),
        home: const LoopShell(),
      ),
    );
    await settle(t);
    await shoot(t, 'phone-home');
    await away(t);
  });

  testWidgets('chat: a session at work, step by step', (t) async {
    await phone(t);
    await t.pumpWidget(
      MaterialApp(
        debugShowCheckedModeBanner: false,
        theme: loopTheme(),
        home: const ChatPage(
          dir: 'acme-shop',
          sessionId: 'checkout',
          title: 'Checkout',
          project: 'Acme Shop',
        ),
      ),
    );
    await settle(t, 3);
    final at = now - 3 * 60000;
    bridge.hear({
      't': 'chat',
      'sessionId': 'checkout',
      'reset': true,
      'items': [
        {
          'k': 'user',
          'id': 'u0',
          'text': 'Morning. Is last night\'s staging deploy healthy?',
          'at': at - 20 * 60000,
        },
        {
          'k': 'text',
          'id': 'a0',
          'text':
              'Yes. Staging is on last night\'s build and its health check '
              'has passed for nine hours straight.',
          'at': at - 20 * 60000 + 5000,
        },
        {
          'k': 'user',
          'id': 'u1',
          'text': 'Big carts time out at checkout. Can you find out why?',
          'at': at,
        },
        {
          'k': 'text',
          'id': 'a1',
          'text':
              "I'll look at the checkout handler and the payment client first.",
          'at': at + 4000,
        },
        {
          'k': 'tool',
          'id': 't1',
          'name': 'Read',
          'title': 'Read file',
          'sub': 'src/checkout/pay.ts',
          'kind': 'read',
          'at': at + 6000,
        },
        {'k': 'result', 'id': 't1', 'ok': true, 'has': true},
        {
          'k': 'tool',
          'id': 't2',
          'name': 'Grep',
          'title': 'Searched code',
          'sub': 'timeout',
          'kind': 'read',
          'at': at + 9000,
        },
        {'k': 'result', 'id': 't2', 'ok': true, 'has': true},
        {
          'k': 'tool',
          'id': 't3',
          'name': 'Edit',
          'title': 'Edited file',
          'sub': 'src/checkout/pay.ts',
          'kind': 'edit',
          'lines': {'add': 9, 'del': 2},
          'at': at + 20000,
        },
        {'k': 'result', 'id': 't3', 'ok': true, 'has': true},
        {
          'k': 'tool',
          'id': 't4',
          'name': 'Bash',
          'title': 'Ran command',
          'sub': 'Run the checkout tests',
          'kind': 'run',
          'at': at + 26000,
        },
        {'k': 'result', 'id': 't4', 'ok': true, 'has': true},
        {
          'k': 'text',
          'id': 'a2',
          'text':
              'Found it. The payment call gave up after **5 seconds**, and '
              'pricing a big cart takes longer than that.\n\n'
              '- The timeout is now 30 seconds\n'
              '- A 504 from the gateway is retried once\n'
              '- All 212 tests pass\n\n'
              'Want me to put it on staging?',
          'at': at + 41000,
        },
      ],
    });
    await settle(t);
    await shoot(t, 'phone-chat');
    bridge.chatClose();
    await away(t);
  });

  testWidgets('voice mode: talking to one session, eyes closed', (t) async {
    await phone(t);
    final m = t.binding.defaultBinaryMessenger;
    m.setMockMethodCallHandler(
      const MethodChannel('plugin.csdcorp.com/speech_to_text'),
      (c) async => switch (c.method) {
        'has_permission' || 'initialize' || 'listen' => true,
        'locales' => <String>['en_IN:English (India)'],
        _ => null,
      },
    );
    m.setMockMethodCallHandler(
      const MethodChannel('flutter_tts'),
      (c) async => switch (c.method) {
        'getVoices' => [
          {'name': 'English India', 'locale': 'en-IN'},
        ],
        _ => 1,
      },
    );
    addTearDown(() {
      m.setMockMethodCallHandler(
        const MethodChannel('plugin.csdcorp.com/speech_to_text'),
        null,
      );
      m.setMockMethodCallHandler(const MethodChannel('flutter_tts'), null);
    });

    await t.pumpWidget(
      MaterialApp(
        debugShowCheckedModeBanner: false,
        theme: loopTheme(),
        home: const TalkPage(
          dir: 'acme-shop',
          sessionId: 'checkout',
          server: '',
          title: 'Checkout',
        ),
      ),
    );
    await settle(t, 4);
    // What the phone has heard so far, mid-sentence.
    Voice.I.heard.value = 'and make the retry wait two seconds first';
    await settle(t, 3);
    await shoot(t, 'phone-voice');
    Voice.I.heard.value = '';
    await away(t);
  });
}
